      <div className="title2">
        <h1>Mon offre de services</h1>
        <h2>Voici les prestations sur lesquelles je peux intervenir</h2>
        <hr className="trait"></hr>
      </div>

      <div className="presta">
        
      </div>
    </main>
  );


}

export default Services;
